"use client";

import {
  type AnimationOptions,
  type AnimationPlaybackControls,
  type DOMKeyframesDefinition,
  useAnimate,
  useReducedMotion,
} from "motion/react";
import { type CSSProperties, useEffect, useRef } from "react";

// Generated by strokekit. Colors follow --sk-stroke; prefers-reduced-motion shows the final frame.
const css = `
.sk-gamr2h-0 {
  stroke: var(--sk-stroke, #f97316);
  stroke-width: 2;
  fill-opacity: 0.2;
  stroke-dasharray: 0.25 1;
  stroke-dashoffset: 0;
}
.sk-gamr2h-1 {
  stroke: var(--sk-stroke, #0f766e);
  stroke-width: 2;
  fill-opacity: 0.2;
  stroke-dasharray: 0.25 1;
  stroke-dashoffset: 0;
}
.sk-gamr2h-2 {
  stroke: var(--sk-stroke, #14b8a6);
  stroke-width: 2;
  fill-opacity: 0.2;
  stroke-dasharray: 0.25 1;
  stroke-dashoffset: 0;
}
.sk-gamr2h-3 {
  stroke: var(--sk-stroke, #f0fdfa);
  stroke-width: 2;
  fill-opacity: 0.2;
  stroke-dasharray: 0.25 1;
  stroke-dashoffset: 0;
}
.sk-gamr2h-4 {
  stroke: var(--sk-stroke, #134e4a);
  stroke-width: 2;
  fill-opacity: 0.2;
  stroke-dasharray: 0.25 1;
  stroke-dashoffset: 0;
}
@media (prefers-reduced-motion: reduce) {
  .sk-gamr2h * {
    animation: none;
  }
  .sk-gamr2h-0 {
    stroke-dasharray: none;
    fill-opacity: 1;
  }
  .sk-gamr2h-1 {
    stroke-dasharray: none;
    fill-opacity: 1;
  }
  .sk-gamr2h-2 {
    stroke-dasharray: none;
    fill-opacity: 1;
  }
  .sk-gamr2h-3 {
    stroke-dasharray: none;
    fill-opacity: 1;
  }
  .sk-gamr2h-4 {
    stroke-dasharray: none;
    fill-opacity: 1;
  }
}
`;

type Track = { selector: string; keyframes: DOMKeyframesDefinition; options: AnimationOptions };

const tracks: Track[] = [
  {
    selector: ".sk-gamr2h-0",
    keyframes: {
      strokeDashoffset: [0, -0.75],
    },
    options: {
      duration: 1.2,
      delay: 0,
      ease: "easeInOut",
      times: [0, 1],
      repeat: Number.POSITIVE_INFINITY,
      repeatType: "reverse",
    },
  },
  {
    selector: ".sk-gamr2h-1",
    keyframes: {
      strokeDashoffset: [0, -0.75],
    },
    options: {
      duration: 1.2,
      delay: 0,
      ease: "easeInOut",
      times: [0, 1],
      repeat: Number.POSITIVE_INFINITY,
      repeatType: "reverse",
    },
  },
  {
    selector: ".sk-gamr2h-2",
    keyframes: {
      strokeDashoffset: [0, -0.75],
    },
    options: {
      duration: 1.2,
      delay: 0,
      ease: "easeInOut",
      times: [0, 1],
      repeat: Number.POSITIVE_INFINITY,
      repeatType: "reverse",
    },
  },
  {
    selector: ".sk-gamr2h-3",
    keyframes: {
      strokeDashoffset: [0, -0.75],
    },
    options: {
      duration: 1.2,
      delay: 0,
      ease: "easeInOut",
      times: [0, 1],
      repeat: Number.POSITIVE_INFINITY,
      repeatType: "reverse",
    },
  },
  {
    selector: ".sk-gamr2h-4",
    keyframes: {
      strokeDashoffset: [0, -0.75],
    },
    options: {
      duration: 1.2,
      delay: 0,
      ease: "easeInOut",
      times: [0, 1],
      repeat: Number.POSITIVE_INFINITY,
      repeatType: "reverse",
    },
  },
];

const visuallyHidden: CSSProperties = {
  position: "absolute",
  width: 1,
  height: 1,
  padding: 0,
  margin: -1,
  overflow: "hidden",
  clip: "rect(0, 0, 0, 0)",
  whiteSpace: "nowrap",
  border: 0,
};

export type PicoLoaderProps = {
  /** Width and height (number = px). Defaults to the SVG's own size. */
  size?: number | string;
  /** Playback speed multiplier: 2 plays twice as fast. */
  speed?: number;
  /** true repeats forever, false plays once. Defaults to the exported animation. */
  loop?: boolean;
  paused?: boolean;
  className?: string;
  /** Accessible name. Defaults to "Carregando". */
  label?: string;
};

export function PicoLoader({
  size,
  speed = 1,
  loop,
  paused = false,
  className,
  label = "Carregando",
}: PicoLoaderProps) {
  const [scope, animate] = useAnimate<SVGSVGElement>();
  const reducedMotion = useReducedMotion();
  const controls = useRef<AnimationPlaybackControls[]>([]);

  useEffect(() => {
    if (reducedMotion) return;
    controls.current = tracks.map((track) =>
      animate(track.selector, track.keyframes, {
        ...track.options,
        ...(loop === undefined ? {} : { repeat: loop ? Number.POSITIVE_INFINITY : 0 }),
      }),
    );
    return () => {
      for (const control of controls.current) control.stop();
      controls.current = [];
    };
  }, [animate, loop, reducedMotion]);

  useEffect(() => {
    for (const control of controls.current) {
      control.speed = speed;
      if (paused) control.pause();
      else control.play();
    }
  }, [speed, paused, loop, reducedMotion]);

  return (
    <span role="status" className={className} style={{ display: "inline-flex" }}>
      <svg
        viewBox="0 0 200 140"
        width={size ?? 200}
        height={size ?? 140}
        className="sk-gamr2h"
        ref={scope}
        aria-hidden="true"
      >
        <style>{css}</style>
        <title>{"Pico"}</title>
        <circle cx="150" cy="38" r="18" fill="#f97316" pathLength="1" className="sk-gamr2h-0" />
        <g fill="#0f766e">
          <polygon points="10,128 78,26 146,128" pathLength="1" className="sk-gamr2h-1" />
          <polygon points="92,128 140,58 190,128" fill="#14b8a6" pathLength="1" className="sk-gamr2h-2" />
        </g>
        <path d="M58 56 L78 26 L98 56 L86 50 L78 60 L70 50 Z" fill="#f0fdfa" pathLength="1" className="sk-gamr2h-3" />
        <rect x="10" y="126" width="180" height="6" rx="3" fill="#134e4a" pathLength="1" className="sk-gamr2h-4" />
      </svg>
      <span style={visuallyHidden}>{label}</span>
    </span>
  );
}
